// Generated by tabmill (templates/extension/popup) — do not edit (ADR-0008).
// Required on every extension: title, privacy line, UTM-tagged CTA, "Built by Lamill" mark + footer.
import { config } from "@/generated/config";

function el<K extends keyof HTMLElementTagNameMap>(
  tag: K,
  props: Partial<HTMLElementTagNameMap[K]> = {},
  ...children: (Node | string)[]
): HTMLElementTagNameMap[K] {
  const node = Object.assign(document.createElement(tag), props);
  node.append(...children);
  return node;
}

function externalLink(href: string, text: string, className = ""): HTMLAnchorElement {
  return el("a", { href, target: "_blank", rel: "noopener", className }, text);
}

/** Render the branded popup shell into `root`; returns the element the feature mounts into. */
export function renderShell(root: HTMLElement): HTMLElement {
  const feature = el("section", { className: "lm-feature" });
  const privacy = el("p", { className: "lm-privacy" }, config.privacy);
  privacy.dataset.testid = "privacy";
  root.append(
    el(
      "main",
      { className: "lm-shell" },
      el("h1", { className: "lm-title" }, config.name),
      feature,
      privacy,
      externalLink(config.ctaUrl, config.ctaText, "lm-cta"),
      el(
        "footer",
        { className: "lm-footer" },
        el("span", { className: "lm-mark", ariaHidden: "true" }, "L"),
        "Built by ",
        externalLink(config.lamillUrl, "Lamill"),
      ),
    ),
  );
  return feature;
}
